    internal static int PkNameMsg(System.Text.StringBuilder msg, int why, byte[] b, int from, int to) {
        // `unknown engine: "foo"`: the reason's sentence and the name as given (printable ASCII only, cut at 64 bytes).
        PkerrEmitName(msg, why);
        emon.Port.TextAscii(msg, ": ");
        emon.Port.TextCp(msg, 34);
        int i = from;
        int c = 0;
        while ((i < to) && ((i - from) < 64)) {
            c = emon.Port.BlobU8(b, i);
            if ((c < 32) || (c > 126)) {
                c = 63;
            }
            emon.Port.TextCp(msg, c);
            i += 1;
        }
        emon.Port.TextCp(msg, 34);
        return why;
    }
    public static int PkParseEngines(byte[] b, int from, int to, emon.Port.Cells @out, System.Text.StringBuilder msg) {
        // Read a comma-separated list of engine names (`tesseract,ppocr`, spaces around a name allowed; an option's value) and push their ids to `out`. 0, or `pkerr-unknown-engine` with the name in `msg`.
        int s = from;
        int i = from;
        int c = 44;
        int a = 0;
        int z = 0;
        int code = 0;
        while (i <= to) {
            c = 44;
            if (i < to) {
                c = emon.Port.BlobU8(b, i);
            }
            if (c == 44) {
                a = s;
                z = i;
                while ((a < z) && (emon.Port.BlobU8(b, a) == 32)) {
                    a += 1;
                }
                while ((a < z) && (emon.Port.BlobU8(b, z - 1) == 32)) {
                    z -= 1;
                }
                if (z > a) {
                    code = EngFind(b, a, z);
                    if (code < 0) {
                        return PkNameMsg(msg, PkerrUnknownEngine(), b, a, z);
                    }
                    emon.Port.CellsPush(@out, code);
                }
                s = i + 1;
            }
            i += 1;
        }
        return 0;
    }
