                c = emon.Port.BlobU8(b, i);
            }
            if (c == 44) {
                a = s;
                z = i;
                while ((a < z) && (emon.Port.BlobU8(b, a) == 32)) {
                    a += 1;
                }
                while ((a < z) && (emon.Port.BlobU8(b, z - 1) == 32)) {
                    z -= 1;
                }
                if (z > a) {
                    code = Packdata.PkidFind(b, a, z);
                    if (code < 0) {
                        return PkNameMsg(msg, PkerrUnknownPack(), b, a, z);
                    }
                    emon.Port.CellsPush(@out, code);
                }
