    public static int PkExplain(int code, emon.Port.Cells subject, System.Text.StringBuilder msg) {
        // The sentence of a refusal of `pk-resolve` or `pk-record-engines`: the reason, then its subject (`subject` is what the call left in `out`).
        PkerrEmitName(msg, code);
        if (code == PkerrUnknownEngine()) {
            emon.Port.TextAscii(msg, ": ");
            emon.Port.TextI32(msg, emon.Port.CellsAt(subject, 0));
        }
        if (code == PkerrUnknownPack()) {
            emon.Port.TextAscii(msg, ": ");
            emon.Port.TextI32(msg, emon.Port.CellsAt(subject, 0));
        }
        if (code == PkerrUnknownClass()) {
            emon.Port.TextAscii(msg, ": ");
            emon.Port.TextI32(msg, emon.Port.CellsAt(subject, 0));
        }
        if (code == PkerrBadLanguage()) {
            emon.Port.TextAscii(msg, ": ");
            emon.Port.TextI32(msg, emon.Port.CellsAt(subject, 0));
        }
        if ((code == PkerrNotOcr()) || (code == PkerrEngineClass())) {
            emon.Port.TextAscii(msg, ": ");
            emon.Port.TextCp(msg, 34);
            EngEmitName(msg, emon.Port.CellsAt(subject, 0));
            emon.Port.TextCp(msg, 34);
        }
        if (code == PkerrEngineClass()) {
            emon.Port.TextAscii(msg, " on ");
            emon.Port.TextCp(msg, 34);
            PclsEmitName(msg, emon.Port.CellsAt(subject, 1));
            emon.Port.TextCp(msg, 34);
        }
        return code;
    }
    internal static int PkMark(emon.Port.Cells c, int at, int v) {
        // Mark a pack of the resolution's scratch: 1 needed, 2 conditional (the fallback partner's), which a needed mark is never lowered to.
        if (v == 1) {
            emon.Port.CellsSet(c, at, 1);
        } else if (emon.Port.CellsAt(c, at) == 0) {
            emon.Port.CellsSet(c, at, 2);
        }
        return 0;
    }
    internal static int PkHas(emon.Port.Cells c, int from, int v) {
        // 1 when `v` is among the cells of `c` from `from` on.
        int n = emon.Port.CellsLen(c);
        int i = from;
        while (i < n) {
            if (emon.Port.CellsAt(c, i) == v) {
                return 1;
            }
            i += 1;
        }
        return 0;
    }
    internal static int PkLangAdd(emon.Port.Cells c, int @base, int lang) {
        // Insert the language into the sorted, duplicate-free list that starts at `base` of `c`.
        int i = @base;
        int n = emon.Port.CellsLen(c);
        int at = -1;
        int v = 0;
        int prev = 0;
        while ((i < n) && (at < 0)) {
            v = emon.Port.CellsAt(c, i);
            if (v == lang) {
                return 0;
            }
            if (v > lang) {
                at = i;
            }
            i += 1;
        }
        if (at < 0) {
            emon.Port.CellsPush(c, lang);
            return 0;
        }
        emon.Port.CellsPush(c, 0);
        i = emon.Port.CellsLen(c) - 1;
        while (i > at) {
            prev = emon.Port.CellsAt(c, i - 1);
            emon.Port.CellsSet(c, i, prev);
            i -= 1;
        }
        emon.Port.CellsSet(c, at, lang);
        return 0;
    }
    internal static int PkFail(emon.Port.Cells @out, int code, int a, int b) {
        // Refuse: `out` holds the subject (what `pk-explain` writes) and the reason is the answer.
        emon.Port.CellsDrop(@out, 0);
        emon.Port.CellsPush(@out, a);
        emon.Port.CellsPush(@out, b);
        return code;
    }
    public static int PkResolve(int pclass, int flags, emon.Port.Cells langs, emon.Port.Cells engines, emon.Port.Cells installed, emon.Port.Cells @out, emon.Port.Cells scratch) {
        // D896's `prepare()`, as kin policy: the packs a conversion needs and which of them are missing.
        // pclass: the platform class (`pcls`). flags: `pkf-osd` when orientation and script detection are wanted. langs: packed ISO 639-3 cells; none means English.
        // engines: the engines asked for (`eng`); none means the class's turnkey default. installed: the codes (`pkid`) of the packs present.
        // out: rows `[state engine pack lang]` (`pstate`). The packs needed, in the catalogue's order, `installed` or `missing`; then the (engine, language) pairs no pack of the
        // catalogue reads, `unsupported` (pack 0), sorted by engine then language. The order does not depend on the order or repetition of the inputs.
        // On a refusal the answer is the reason (`pkerr`) and `out` holds `[subject-a subject-b]` for `pk-explain`. scratch: working cells.
        emon.Port.CellsDrop(@out, 0);
        emon.Port.CellsDrop(scratch, 0);
        if (PkClassKnown(pclass) == 0) {
            return PkFail(@out, PkerrUnknownClass(), pclass, 0);
        }
        int np = 24;
        int ne = 7;
        int sel = np + 1;
        int lb = (np + 1) + ne;
        int i = 0;
        int r = 0;
        int v = 0;
        int eng = 0;
        int p = 0;
        int pe = 0;
        int needs = 0;
        int pk = 0;
        int lang = 0;
        int j = 0;
        int sv = 0;
        int want = 0;
        while (i < lb) {
            emon.Port.CellsPush(scratch, 0);
            i += 1;
        }
        if (emon.Port.CellsLen(engines) == 0) {
            r = PkEnRow(PkDefaultEngine(pclass));
            if (r >= 0) {
                emon.Port.CellsSet(scratch, sel + r, 1);
            }
        } else {
            i = 0;
            while (i < emon.Port.CellsLen(engines)) {
                eng = emon.Port.CellsAt(engines, i);
                r = PkEnRow(eng);
                if (r < 0) {
                    return PkFail(@out, PkerrUnknownEngine(), eng, 0);
                }
                if (EnTable[r * 8 + 2] != EkindOcr()) {
                    return PkFail(@out, PkerrNotOcr(), eng, 0);
                }
                if (PkEngineOn(eng, pclass) == 0) {
                    return PkFail(@out, PkerrEngineClass(), eng, pclass);
                }
                emon.Port.CellsSet(scratch, sel + r, 1);
                i += 1;
            }
        }
        if (emon.Port.CellsAt(scratch, sel + PkEnRow(EngAppleVision())) == 1) {
            eng = PkFallbackEngine(pclass);
            r = PkEnRow(eng);
            if ((r >= 0) && (emon.Port.CellsAt(scratch, sel + r) == 0)) {
                emon.Port.CellsSet(scratch, sel + r, 2);
            }
        }
        if (emon.Port.CellsLen(langs) == 0) {
            emon.Port.CellsPush(scratch, PkLangEng());
        } else {
            i = 0;
            while (i < emon.Port.CellsLen(langs)) {
                lang = emon.Port.CellsAt(langs, i);
                if (lang <= 0) {
                    return PkFail(@out, PkerrBadLanguage(), lang, 0);
                }
                PkLangAdd(scratch, lb, lang);
                i += 1;
            }
        }
        i = 0;
        while (i < emon.Port.CellsLen(installed)) {
            p = emon.Port.CellsAt(installed, i);
            if (PkPackKnown(p) == 0) {
                return PkFail(@out, PkerrUnknownPack(), p, 0);
            }
            i += 1;
        }
        r = 0;
        while (r < ne) {
            sv = emon.Port.CellsAt(scratch, sel + r);
            if (sv > 0) {
                eng = EnTable[r * 8 + 0];
                needs = EnTable[r * 8 + 7];
                p = 1;
                while (p <= np) {
                    pe = PkPackEngine(p);
                    pk = PkPackKind(p);
                    if (((pe == eng) || (pe == 0)) && ((needs & pk) != 0)) {
                        if (pk == PkindOsd()) {
                            if ((flags & PkfOsd()) != 0) {
                                PkMark(scratch, p, sv);
                            }
                        }
                        if ((pk == PkindDetector()) || (pk == PkindClassifier())) {
                            PkMark(scratch, p, sv);
                        }
                    }
                    p += 1;
                }
                j = lb;
                while (j < emon.Port.CellsLen(scratch)) {
                    lang = emon.Port.CellsAt(scratch, j);
                    want = sv;
                    if (sv == 2) {
                        if (Ocrloc.OlHas(PkEngineOen(EngAppleVision()), lang) == 0) {
                            want = 1;
                        }
                    }
                    p = PkPackFor(eng, PkindRecognizer(), lang);
                    if ((p != 0) && ((needs & PkindRecognizer()) != 0)) {
                        PkMark(scratch, p, want);
                    }
                    p = PkPackFor(eng, PkindLexicon(), lang);
                    if ((p != 0) && ((needs & PkindLexicon()) != 0)) {
                        PkMark(scratch, p, want);
                    }
                    j += 1;
                }
            }
            r += 1;
        }
        emon.Port.CellsDrop(@out, 0);
        p = 1;
        while (p <= np) {
            if (emon.Port.CellsAt(scratch, p) > 0) {
                v = PstateMissing();
                if (emon.Port.CellsAt(scratch, p) == 2) {
                    v = PstateConditional();
                }
                if (PkHas(installed, 0, p) == 1) {
                    v = PstateInstalled();
                }
                emon.Port.CellsPush(@out, v);
                emon.Port.CellsPush(@out, PkPackEngine(p));
                emon.Port.CellsPush(@out, p);
                emon.Port.CellsPush(@out, 0);
            }
            p += 1;
        }
        r = 0;
        while (r < ne) {
            sv = emon.Port.CellsAt(scratch, sel + r);
            if ((sv > 0) && ((EnTable[r * 8 + 7] & PkindRecognizer()) != 0)) {
                eng = EnTable[r * 8 + 0];
                j = lb;
                while (j < emon.Port.CellsLen(scratch)) {
                    lang = emon.Port.CellsAt(scratch, j);
                    want = sv;
                    if (sv == 2) {
                        if (Ocrloc.OlHas(PkEngineOen(EngAppleVision()), lang) == 0) {
                            want = 1;
                        }
                    }
                    if ((want == 1) && (PkPackFor(eng, PkindRecognizer(), lang) == 0)) {
                        emon.Port.CellsPush(@out, PstateUnsupported());
                        emon.Port.CellsPush(@out, eng);
                        emon.Port.CellsPush(@out, 0);
                        emon.Port.CellsPush(@out, lang);
                    }
                    j += 1;
                }
            }
            r += 1;
        }
        return 0;
    }
    public static int PkRows(emon.Port.Cells @out) {
        // How many rows `pk-resolve` left in `out`.
        return emon.Port.CellsLen(@out) / 4;
    }
    public static int PkRowState(emon.Port.Cells @out, int row) {
        return emon.Port.CellsAt(@out, row * 4);
    }
    public static int PkRowEngine(emon.Port.Cells @out, int row) {
        return emon.Port.CellsAt(@out, (row * 4) + 1);
    }
    public static int PkRowPack(emon.Port.Cells @out, int row) {
        return emon.Port.CellsAt(@out, (row * 4) + 2);
    }
    public static int PkRowLang(emon.Port.Cells @out, int row) {
        return emon.Port.CellsAt(@out, (row * 4) + 3);
    }
    public static int PkMissing(emon.Port.Cells @out) {
        // How many packs of the resolution are missing.
        int i = 0;
        int n = 0;
        while (i < PkRows(@out)) {
            if (PkRowState(@out, i) == PstateMissing()) {
                n += 1;
            }
            i += 1;
        }
        return n;
    }
    public static int PkRecordEngines(emon.Port.Cells @out, int pclass, emon.Port.Cells avail) {
        // The engine table of a conversion, for a transcript's `:pk-engines`: one `[eng caps role]` row for each engine of `avail` (engine ids, any order, repeats allowed),
        // in the table's order. `caps` is the ceiling the table declares and `role` the default role on the class. 0, or the reason (`pkerr`) with the subject left in `out`.
        emon.Port.CellsDrop(@out, 0);
        if (PkClassKnown(pclass) == 0) {
            return PkFail(@out, PkerrUnknownClass(), pclass, 0);
        }
        int i = 0;
        int eng = 0;
        while (i < emon.Port.CellsLen(avail)) {
            eng = emon.Port.CellsAt(avail, i);
            if (PkEngineKnown(eng) == 0) {
                return PkFail(@out, PkerrUnknownEngine(), eng, 0);
            }
            if (PkEngineOn(eng, pclass) == 0) {
                return PkFail(@out, PkerrEngineClass(), eng, pclass);
            }
            i += 1;
        }
        int r = 0;
        int rowEng = 0;
        int role = 0;
        while (r < 7) {
            rowEng = EnTable[r * 8 + 0];
            if (PkHas(avail, 0, rowEng) == 1) {
                role = PkRoleDefault(rowEng, pclass);
                emon.Port.CellsPush(@out, rowEng);
                emon.Port.CellsPush(@out, EnTable[r * 8 + 4]);
                emon.Port.CellsPush(@out, role);
            }
            r += 1;
        }
        return 0;
    }
}
